      '5.1e9':[{"id": "s4i2tk5zvf", "name": "Tungang saltpeter works (to be named)", "type": "outpost", "px": 492, "py": 1255, "notes": "Added 2026-11-12 (the owner: every polity something others lack; openworld/TRADE-GOODS.md): a cave saltpeter works of the Tungang Union, rich saltpeter (200) 75 km from Loj Twenny; with Rift-line salvage, the Union's export.", "createdAt": "2026-11-12T00:00:00.000Z"}, {"id": "s08nld4zx3", "name": "Fellgang gold camp (to be named)", "type": "outpost", "px": 438, "py": 1448, "notes": "Added 2026-11-12 (the owner: every polity something others lack): a Fellgang summer gold camp on decent gold (140), 24 km from Wildcat.", "createdAt": "2026-11-12T00:00:00.000Z"}, {"id": "sd3o47efic", "name": "Coyote salt works (to be named)", "type": "outpost", "px": 1190, "py": 463, "notes": "Added 2026-11-12 (the owner: every polity something others lack): the Coyote Kingdom's salt works on rich rock salt (229), where every nearby settlement is short of salt; some sulfur (low grade).", "createdAt": "2026-11-12T00:00:00.000Z"}],
      '5.1e8':[{"id": "sz5upw419z", "name": "Iziz iron mine (to be named)", "type": "village", "px": 936, "py": 1013, "notes": "Added 2026-11-12 (the owner: Iziz needs decent iron): a mining hamlet at the near tip of a rich iron field (180), 78 km SW of Iziz on Iziz's land; an 80 km road to the city. Talia's iron tribute is a second source.", "createdAt": "2026-11-12T00:00:00.000Z"}, {"id": "sowif50v6z", "name": "Voth iron mine (to be named)", "type": "village", "px": 732, "py": 1014, "notes": "Added 2026-11-12 (the owner: Voth needs decent iron): a mine hamlet on a rich iron field (2,936 km2), 22 km W of Voth; edit_513 reshapes the bay nearby.", "createdAt": "2026-11-12T00:00:00.000Z"}, {"id": "s7f7ct6r5p", "name": "Reed upriver fields (to be named)", "type": "village", "px": 1297, "py": 683, "notes": "Added 2026-11-12 (the owner: more fertile ground for Reed): Reed stays on its salt lake; its fields hamlet stands 35 km up the Rifar al-Qasr (-779 m, Aw 31 C, 1,239 mm), its landing at the river's freshwater mouth by the lake.", "createdAt": "2026-11-12T00:00:00.000Z"}, {"id": "s1b3vyhdck", "name": "Pylon tin outpost (to be named)", "type": "outpost", "px": 875, "py": 1015, "notes": "Added 2026-11-12 (the owner: Pylon closer to tin): Pylon stays round its Monolith; a tin outpost at the edge of a rich tin field (200, placers nearby), 29 km SSE by a nearly level road.", "createdAt": "2026-11-12T00:00:00.000Z"}],
